import * as net from 'node:net';
function main(): void {
  const srv = net.createServer((s: any) => { s.end('x'); });
  srv.listen(0, '127.0.0.1', async (): Promise<void> => {
    console.log('listening');
    await new Promise<void>((r) => setTimeout(r, 5));
    throw new Error('boom');
  });
}
